use ark_ff::{self, BigInt};

use zkhash::{fields::babybear::{self, FpBabyBear}, poseidon2::{poseidon2::Poseidon2, poseidon2_instance_babybear::POSEIDON2_BABYBEAR_16_PARAMS}};

fn poseidon2_pbt(input : [u32; 16]) -> [u32; 16] {
    let input_vec = input.map(|x| FpBabyBear::from(x));
    let poseidon2 = Poseidon2::new(&POSEIDON2_BABYBEAR_16_PARAMS);
    let output : Vec<ark_ff::Fp<ark_ff::MontBackend<babybear::FqConfig, 1>, 1>> = poseidon2.permutation(&input_vec);
    let output_vec : Vec<ark_ff::Fp<ark_ff::MontBackend<babybear::FqConfig, 1>, 1>> = output.into_iter().map(|x| x).collect();
    let output_vec_bigint : Vec<BigInt<1>> = output_vec.into_iter().map(|x| x.into()).collect();
    let output_vec_u32 : Vec<u32> = output_vec_bigint.iter().map(|x| x.0[0] as u32).collect();
    let output: [u32; 16] = [output_vec_u32[0],
                             output_vec_u32[1],
                             output_vec_u32[2],
                             output_vec_u32[3],
                             output_vec_u32[4],
                             output_vec_u32[5],
                             output_vec_u32[6],
                             output_vec_u32[7],
                             output_vec_u32[8],
                             output_vec_u32[9],
                             output_vec_u32[10],
                             output_vec_u32[11],
                             output_vec_u32[12],
                             output_vec_u32[13],
                             output_vec_u32[14],
                             output_vec_u32[15],
                            ];
    output
}

